TUTORIALS.append({'title': 'PDF-1. Setup: folders, packages, urls', 'category': 'programming', 'order': 1, 'summary': 'Do this first: the app layout, pip packages, settings and urls.', 'content': '<p>Step 1 of 6. Create the app folder with this layout. <code>__init__.py</code> is empty. Add <code>"converter"</code> to <code>INSTALLED_APPS</code> and include its urls. No models, no migrations: files are processed in memory and sent straight back, nothing is saved.</p>\n<p>Packages (one per tool; a tool whose package is missing switches itself off, the rest keep working):</p>\n<pre><code class="language-plaintext">pip install pypdf          # merge, pages, split, rotate\npip install pdfplumber     # PDF -&gt; Excel (openpyxl is already there)\npip install pdf2docx       # PDF -&gt; Word (pulls in PyMuPDF, numpy, opencv-python-headless)\nsudo systemctl restart gunicorn\n</code></pre>\n<p>Add a sidebar link to <code>{% url \'converter\' %}</code> in base.html. If nginx limits uploads, raise <code>client_max_body_size 50M;</code>.</p>\n<h3>Layout</h3>\n<pre><code class="language-plaintext">converter/\n    __init__.py\n    apps.py\n    urls.py\n    pdftools.py\n    views.py\n    templates/converter/page.html\n</code></pre>\n<h3>urls.py of the project</h3>\n<pre><code class="language-python">path("converter/", include("converter.urls")),\n</code></pre>\n'})

TUTORIALS.append({'title': 'PDF-2. apps.py', 'category': 'programming', 'order': 2, 'summary': 'App config.', 'content': '<p>Step 2 of 6. Save as <code>converter/apps.py</code>.</p>\n<h3>apps.py</h3>\n<pre><code class="language-python">from django.apps import AppConfig\n\n\nclass ConverterConfig(AppConfig):\n    default_auto_field = "django.db.models.BigAutoField"\n    name = "converter"\n    verbose_name = "Конвертер PDF"\n</code></pre>\n'})

TUTORIALS.append({'title': 'PDF-3. urls.py', 'category': 'programming', 'order': 3, 'summary': 'URL names converter and converter-run.', 'content': '<p>Step 3 of 6. Save as <code>converter/urls.py</code>.</p>\n<h3>urls.py</h3>\n<pre><code class="language-python">from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    path("", views.page, name="converter"),\n    path("run/&lt;str:tool&gt;/", views.run, name="converter-run"),\n]\n</code></pre>\n'})

TUTORIALS.append({'title': 'PDF-4. pdftools.py', 'category': 'programming', 'order': 4, 'summary': 'The tools: merge, pages (pick/reorder/delete), split to ZIP, rotate, PDF to Word, PDF to Excel. Bytes in, bytes out, nothing saved.', 'content': '<p>Step 4 of 6. Save as <code>converter/pdftools.py</code>.</p>\n<h3>pdftools.py</h3>\n<pre><code class="language-python">"""\nThe PDF tools themselves: bytes in, bytes out. No Django and no disk: nothing is ever saved.\n\nEach tool needs one package. If it is not installed, the tool is switched off on the page\n(see AVAILABLE) and the other tools keep working:\n    pypdf       merge, pages, split, rotate          pip install pypdf\n    pdf2docx    PDF → Word                            pip install pdf2docx\n    pdfplumber  PDF → Excel (+ openpyxl, already in the project)   pip install pdfplumber\n"""\nimport io\nimport re\nimport zipfile\n\ntry:\n    from pypdf import PdfReader, PdfWriter\n    from pypdf.errors import PdfReadError\nexcept ImportError:                      # tool switched off on the page\n    PdfReader = PdfWriter = None\n    PdfReadError = Exception\n\ntry:\n    from pdf2docx import Converter\nexcept ImportError:\n    Converter = None\n\ntry:\n    import pdfplumber\nexcept ImportError:\n    pdfplumber = None\n\nAVAILABLE = {\n    "merge": PdfReader is not None,\n    "pages": PdfReader is not None,\n    "split": PdfReader is not None,\n    "rotate": PdfReader is not None,\n    "word": Converter is not None and PdfReader is not None,\n    "excel": pdfplumber is not None and PdfReader is not None,\n}\nPACKAGE = {"merge": "pypdf", "pages": "pypdf", "split": "pypdf", "rotate": "pypdf",\n           "word": "pdf2docx", "excel": "pdfplumber"}\n\n\nclass ToolError(Exception):\n    """A problem the user can fix: shown on the page in Russian."""\n\n\n# ── helpers ─────────────────────────────────────────────────────────────────────────\n\ndef _reader(data):\n    try:\n        reader = PdfReader(io.BytesIO(data))\n    except (PdfReadError, ValueError, OSError):\n        raise ToolError("Файл не похож на PDF или повреждён.")\n    if reader.is_encrypted:\n        try:\n            ok = reader.decrypt("")          # many bank PDFs are "protected" with an empty password\n        except Exception:\n            ok = 0\n        if not ok:\n            raise ToolError("PDF защищён паролем — снимите защиту и попробуйте снова.")\n    return reader\n\n\ndef _bytes(writer):\n    out = io.BytesIO()\n    writer.write(out)\n    return out.getvalue()\n\n\ndef parse_pages(spec, total):\n    """\'1-3, 5, 8-\' -&gt; [0, 1, 2, 4, 7, 8, 9] (0-based, in the order written).\n\n    a-b   pages a to b (b &lt; a goes backwards: \'5-3\' = 5, 4, 3)\n    a-    page a to the end;  -b  first page to b\n    Empty spec = all pages.\n    """\n    spec = (spec or "").replace(" ", "").replace(";", ",")\n    if not spec:\n        return list(range(total))\n    pages = []\n    for part in filter(None, spec.split(",")):\n        m = re.fullmatch(r"(\\d*)-(\\d*)|(\\d+)", part)\n        if not m or part == "-":\n            raise ToolError(f"Не понимаю «{part}». Пишите так: 1-3, 5, 8-")\n        if m.group(3):\n            a = b = int(m.group(3))\n        else:\n            a = int(m.group(1) or 1)\n            b = int(m.group(2) or total)\n        for n in (a, b):\n            if not 1 &lt;= n &lt;= total:\n                raise ToolError(f"Страницы {n} нет: в файле {total} стр.")\n        step = 1 if b &gt;= a else -1\n        pages.extend(range(a - 1, b - 1 + step, step))\n    return pages\n\n\ndef natural_key(name):\n    """\'файл 10.pdf\' after \'файл 2.pdf\'."""\n    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\\d+)", name)]\n\n\n# ── the tools ───────────────────────────────────────────────────────────────────────\n\ndef merge(files):\n    """files = [(name, bytes), ...] -&gt; one PDF, in natural order of the file names."""\n    if len(files) &lt; 2:\n        raise ToolError("Выберите хотя бы два PDF.")\n    writer = PdfWriter()\n    for name, data in sorted(files, key=lambda f: natural_key(f[0])):\n        try:\n            reader = _reader(data)\n        except ToolError as e:\n            raise ToolError(f"{name}: {e}")\n        for page in reader.pages:\n            writer.add_page(page)\n    return _bytes(writer)\n\n\ndef pages(data, keep="", delete=""):\n    """Keep pages in the order written (this also reorders), then drop the ones in delete."""\n    reader = _reader(data)\n    total = len(reader.pages)\n    order = parse_pages(keep, total)\n    drop = set(parse_pages(delete, total)) if delete.strip() else set()\n    order = [i for i in order if i not in drop]\n    if not order:\n        raise ToolError("После удаления не осталось ни одной страницы.")\n    writer = PdfWriter()\n    for i in order:\n        writer.add_page(reader.pages[i])\n    return _bytes(writer)\n\n\ndef split(data, every, stem):\n    """Every N pages -&gt; a separate PDF, all of them in one ZIP."""\n    reader = _reader(data)\n    total = len(reader.pages)\n    if every &lt; 1:\n        raise ToolError("Число страниц в части должно быть 1 или больше.")\n    out = io.BytesIO()\n    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:\n        for start in range(0, total, every):\n            end = min(start + every, total)\n            writer = PdfWriter()\n            for i in range(start, end):\n                writer.add_page(reader.pages[i])\n            label = f"{start + 1:03d}" if end - start == 1 else f"{start + 1:03d}-{end:03d}"\n            z.writestr(f"{stem}_{label}.pdf", _bytes(writer))\n    return out.getvalue()\n\n\ndef rotate(data, spec, angle):\n    """Rotate the listed pages (empty = all) clockwise by 90 / 180 / 270."""\n    if angle not in (90, 180, 270):\n        raise ToolError("Угол поворота: 90, 180 или 270.")\n    reader = _reader(data)\n    chosen = set(parse_pages(spec, len(reader.pages)))\n    writer = PdfWriter()\n    for i, page in enumerate(reader.pages):\n        if i in chosen:\n            page.rotate(angle)\n        writer.add_page(page)\n    return _bytes(writer)\n\n\ndef to_word(data, spec=""):\n    """PDF -&gt; .docx. Works on PDFs with real text; a scan comes out as pictures."""\n    total = len(_reader(data).pages)\n    chosen = parse_pages(spec, total)\n    out = io.BytesIO()\n    cv = Converter(stream=data)\n    try:\n        cv.convert(out, pages=chosen)\n    finally:\n        cv.close()\n    return out.getvalue()\n\n\ndef to_excel(data, spec="", one_sheet=False):\n    """Every table found in the PDF -&gt; .xlsx: a sheet per table, or all on one sheet."""\n    from openpyxl import Workbook\n    from openpyxl.styles import Font\n\n    total = len(_reader(data).pages)\n    chosen = parse_pages(spec, total)\n    wb = Workbook()\n    wb.remove(wb.active)\n    found = 0\n    with pdfplumber.open(io.BytesIO(data)) as pdf:\n        for i in chosen:\n            for k, table in enumerate(pdf.pages[i].extract_tables(), start=1):\n                rows = [[_cell(c) for c in row] for row in table if any(c not in (None, "") for c in row)]\n                if not rows:\n                    continue\n                found += 1\n                if one_sheet:\n                    ws = wb["Таблицы"] if "Таблицы" in wb.sheetnames else wb.create_sheet("Таблицы")\n                    if ws.max_row &gt; 1:\n                        ws.append([])\n                    ws.append([f"Страница {i + 1}, таблица {k}"])\n                    ws.cell(ws.max_row, 1).font = Font(bold=True)\n                else:\n                    ws = wb.create_sheet(f"стр{i + 1}_т{k}"[:31])\n                for row in rows:\n                    ws.append(row)\n    if not found:\n        raise ToolError("Таблиц не найдено. Если это скан (картинка), его нельзя прочитать без распознавания текста.")\n    for ws in wb.worksheets:\n        for col in ws.columns:\n            width = max((len(str(c.value)) for c in col if c.value is not None), default=8)\n            ws.column_dimensions[col[0].column_letter].width = min(max(10, width + 2), 60)\n    out = io.BytesIO()\n    wb.save(out)\n    return out.getvalue()\n\n\ndef _cell(v):\n    """Text from a PDF table cell: numbers like \'1 234 567,89\' become real numbers.\n\n    Codes stay text: an account number (20 digits) or \'007\' would lose digits as a number.\n    """\n    if v is None:\n        return None\n    s = " ".join(str(v).split())\n    num = s.replace("\\u00a0", "").replace(" ", "")\n    if num[:1] in ("\\u00ad", "\\u2212", "\\u2013"):    # PDFs write minus as soft hyphen, − or –\n        num = "-" + num[1:]\n    digits = num.lstrip("-").split(",")[0].split(".")[0]\n    if len(digits) &gt; 15 or (len(digits) &gt; 1 and digits.startswith("0")):\n        return s\n    if re.fullmatch(r"-?\\d+([.,]\\d+)?", num):\n        try:\n            return float(num.replace(",", ".")) if re.search(r"[.,]", num) else int(num)\n        except ValueError:\n            pass\n    return s\n</code></pre>\n'})

TUTORIALS.append({'title': 'PDF-5. views.py', 'category': 'programming', 'order': 5, 'summary': 'The page and run(): checks the upload, calls the tool, returns the file as a download or shows the error in the tool card.', 'content': '<p>Step 5 of 6. Save as <code>converter/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">"""\nPDF converter: one page with a form per tool; each form posts to run(), which answers with\nthe finished file as a download. Nothing is written to disk or to the database: the upload\nis read into memory, processed by pdftools.py, and sent straight back.\n"""\nimport io\nfrom pathlib import Path\n\nfrom django.http import FileResponse\nfrom django.shortcuts import render\nfrom django.views.decorators.http import require_POST\n\nfrom . import pdftools\nfrom .pdftools import ToolError\n\nMAX_MB = 50                                    # per request, all files together\n\nPDF = "application/pdf"\nTOOLS = [  # (key, icon, title, what it does) — in the order shown on the page\n    ("merge", "fa-object-group", "Объединить PDF", "Несколько PDF → один файл"),\n    ("pages", "fa-arrow-down-1-9", "Страницы: выбрать, переставить, удалить", "Новый PDF из нужных страниц в нужном порядке"),\n    ("split", "fa-scissors", "Разделить PDF", "Каждые N страниц → отдельный файл, всё в ZIP"),\n    ("rotate", "fa-rotate-right", "Повернуть страницы", "Все или выбранные страницы на 90°, 180°, 270°"),\n    ("word", "fa-file-word", "PDF → Word", "Текст, абзацы и таблицы в .docx"),\n    ("excel", "fa-file-excel", "PDF → Excel", "Все таблицы из PDF в .xlsx"),\n]\n\n\ndef _context(**extra):\n    tools = [{"key": k, "icon": i, "title": t, "about": a, "on": pdftools.AVAILABLE[k],\n              "package": pdftools.PACKAGE[k]} for k, i, t, a in TOOLS]\n    return {"tools": tools, "max_mb": MAX_MB, **extra}\n\n\ndef page(request):\n    return render(request, "converter/page.html", _context())\n\n\ndef _pdfs(request):\n    """Uploaded PDFs as [(name, bytes)], with the size and type checks."""\n    files = request.FILES.getlist("files")\n    if not files:\n        raise ToolError("Выберите файл.")\n    if sum(f.size for f in files) &gt; MAX_MB * 1024 * 1024:\n        raise ToolError(f"Слишком большие файлы: максимум {MAX_MB} МБ за раз.")\n    out = []\n    for f in files:\n        if not f.name.lower().endswith(".pdf"):\n            raise ToolError(f"{f.name}: нужен файл .pdf")\n        out.append((f.name, f.read()))\n    return out\n\n\ndef _download(data, filename, content_type):\n    return FileResponse(io.BytesIO(data), as_attachment=True, filename=filename, content_type=content_type)\n\n\n@require_POST\ndef run(request, tool):\n    if tool not in pdftools.AVAILABLE:\n        return render(request, "converter/page.html", _context(error={"tool": tool, "text": "Нет такого инструмента."}))\n    if not pdftools.AVAILABLE[tool]:\n        return render(request, "converter/page.html", _context(\n            error={"tool": tool, "text": f"Инструмент выключен: на сервере нет пакета {pdftools.PACKAGE[tool]}."}))\n\n    p = request.POST\n    try:\n        files = _pdfs(request)\n        name, data = files[0]\n        stem = Path(name).stem\n\n        if tool == "merge":\n            return _download(pdftools.merge(files), "объединённый.pdf", PDF)\n        if tool == "pages":\n            result = pdftools.pages(data, p.get("keep", ""), p.get("delete", ""))\n            return _download(result, f"{stem}_страницы.pdf", PDF)\n        if tool == "split":\n            every = int(p.get("every") or 1)\n            return _download(pdftools.split(data, every, stem), f"{stem}_части.zip", "application/zip")\n        if tool == "rotate":\n            result = pdftools.rotate(data, p.get("pages", ""), int(p.get("angle") or 90))\n            return _download(result, f"{stem}_повёрнут.pdf", PDF)\n        if tool == "word":\n            result = pdftools.to_word(data, p.get("pages", ""))\n            return _download(result, f"{stem}.docx",\n                             "application/vnd.openxmlformats-officedocument.wordprocessingml.document")\n        if tool == "excel":\n            result = pdftools.to_excel(data, p.get("pages", ""), one_sheet=p.get("one_sheet") == "1")\n            return _download(result, f"{stem}.xlsx",\n                             "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n    except ToolError as e:\n        message = str(e)\n    except ValueError:\n        message = "Проверьте числа в форме."\n    except Exception as e:                      # a broken PDF can fail deep inside a library\n        message = f"Не получилось обработать файл ({type(e).__name__}). Попробуйте другой файл."\n    return render(request, "converter/page.html", _context(error={"tool": tool, "text": message}))\n</code></pre>\n'})

TUTORIALS.append({'title': 'PDF-6. templates/converter/page.html', 'category': 'programming', 'order': 6, 'summary': 'One card per tool, each its own form. Bootstrap, no JavaScript. Russian UI.', 'content': '<p>Step 6 of 6. Save as <code>converter/templates/converter/page.html</code>.</p>\n<h3>templates/converter/page.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  PDF converter: one card per tool, each card is its own form. No JavaScript.\n  The finished file comes back as a download; nothing is stored on the server.\n  Scoped under .cvt so the dashboard\'s own styles are not touched.\n{% endcomment %}\n\n{% block extra_css %}\n&lt;style&gt;\n  .cvt{--ink:#0B0B0C;--gold:#F2C230;--gd:#C9971A;--gtext:#8C6A12;--rule:#E4E1D8;--muted:#8A867C;--bad:#B3341F}\n  .cvt .hero{background:var(--ink);color:#fff;border-radius:10px;padding:22px 26px;margin-bottom:20px}\n  .cvt .hero .eyebrow{font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold)}\n  .cvt .hero h1{font-weight:500;font-size:26px;margin:6px 0 4px}\n  .cvt .hero p{color:#B9B5AB;font-size:13.5px;margin:0;max-width:80ch}\n  .cvt .tool{border:1px solid var(--rule);border-radius:10px;background:#fff;height:100%;display:flex;flex-direction:column}\n  .cvt .tool.off{opacity:.6}\n  .cvt .tool-head{display:flex;gap:12px;align-items:center;padding:14px 16px;border-bottom:1px solid var(--rule);background:#FAF8F2;border-radius:10px 10px 0 0}\n  .cvt .tool-head i{font-size:22px;color:var(--gd);width:28px;text-align:center}\n  .cvt .tool-head h2{font-size:16px;margin:0;font-weight:600}\n  .cvt .tool-head small{color:var(--muted);display:block;font-size:12.5px}\n  .cvt form{padding:14px 16px;display:flex;flex-direction:column;gap:10px;flex:1}\n  .cvt .form-label{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:3px}\n  .cvt .hint{font-size:12px;color:var(--muted);margin-top:3px}\n  .cvt .btn-go{background:var(--gold);border:none;color:var(--ink);font-weight:600;margin-top:auto;align-self:flex-start;padding:7px 22px}\n  .cvt .btn-go:hover{background:var(--gd)}\n  .cvt .err{background:#FBF3F1;border-left:3px solid var(--bad);color:var(--bad);padding:8px 12px;font-size:13px;border-radius:0 6px 6px 0}\n  .cvt .rules{font-size:13px;color:var(--muted)}\n  .cvt code{color:var(--gtext)}\n&lt;/style&gt;\n{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="cvt container-fluid px-4 py-4"&gt;\n\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;Инструменты&lt;/div&gt;\n    &lt;h1&gt;Конвертер PDF&lt;/h1&gt;\n    &lt;p&gt;Объединить, разделить, переставить и повернуть страницы, перевести PDF в Word или Excel — прямо здесь,\n       без внешних сайтов. Файлы обрабатываются в памяти и сразу возвращаются вам: на сервере ничего не сохраняется.\n       До {{ max_mb }} МБ за раз.&lt;/p&gt;\n  &lt;/div&gt;\n\n  &lt;div class="row row-cols-1 row-cols-lg-2 row-cols-xxl-3 g-3"&gt;\n    {% for t in tools %}\n    &lt;div class="col" id="{{ t.key }}"&gt;\n      &lt;div class="tool{% if not t.on %} off{% endif %}"&gt;\n        &lt;div class="tool-head"&gt;&lt;i class="fas {{ t.icon }}"&gt;&lt;/i&gt;\n          &lt;div&gt;&lt;h2&gt;{{ t.title }}&lt;/h2&gt;&lt;small&gt;{{ t.about }}&lt;/small&gt;&lt;/div&gt;&lt;/div&gt;\n\n        &lt;form method="post" enctype="multipart/form-data" action="{% url \'converter-run\' t.key %}"&gt;\n          {% csrf_token %}\n          {% if error and error.tool == t.key %}&lt;div class="err"&gt;{{ error.text }}&lt;/div&gt;{% endif %}\n\n          {% if not t.on %}\n            &lt;div class="hint"&gt;Выключено: на сервере нет пакета &lt;code&gt;{{ t.package }}&lt;/code&gt;.\n              Администратор: &lt;code&gt;pip install {{ t.package }}&lt;/code&gt;&lt;/div&gt;\n          {% else %}\n\n          {% if t.key == "merge" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF-файлы (два и больше)&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" multiple required&gt;\n              &lt;div class="hint"&gt;Порядок — по именам файлов: «1_договор», «2_приложение», … «10_…» встанет после «9_…».&lt;/div&gt;&lt;/div&gt;\n\n          {% elif t.key == "pages" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" required&gt;&lt;/div&gt;\n            &lt;div&gt;&lt;label class="form-label"&gt;Какие страницы и в каком порядке&lt;/label&gt;\n              &lt;input class="form-control" name="keep" placeholder="например: 3, 1-2, 5-" autocomplete="off"&gt;\n              &lt;div class="hint"&gt;Пусто = все. Порядок как написано, поэтому «3, 1-2» ставит третью страницу первой.&lt;/div&gt;&lt;/div&gt;\n            &lt;div&gt;&lt;label class="form-label"&gt;Удалить страницы&lt;/label&gt;\n              &lt;input class="form-control" name="delete" placeholder="например: 4, 7-9" autocomplete="off"&gt;&lt;/div&gt;\n\n          {% elif t.key == "split" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" required&gt;&lt;/div&gt;\n            &lt;div&gt;&lt;label class="form-label"&gt;Страниц в каждой части&lt;/label&gt;\n              &lt;input class="form-control" type="number" name="every" value="1" min="1" required&gt;\n              &lt;div class="hint"&gt;1 = каждая страница отдельным файлом.&lt;/div&gt;&lt;/div&gt;\n\n          {% elif t.key == "rotate" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" required&gt;&lt;/div&gt;\n            &lt;div class="row g-2"&gt;\n              &lt;div class="col-7"&gt;&lt;label class="form-label"&gt;Страницы&lt;/label&gt;\n                &lt;input class="form-control" name="pages" placeholder="пусто = все" autocomplete="off"&gt;&lt;/div&gt;\n              &lt;div class="col-5"&gt;&lt;label class="form-label"&gt;По часовой&lt;/label&gt;\n                &lt;select class="form-select" name="angle"&gt;&lt;option value="90"&gt;90°&lt;/option&gt;&lt;option value="180"&gt;180°&lt;/option&gt;&lt;option value="270"&gt;270°&lt;/option&gt;&lt;/select&gt;&lt;/div&gt;\n            &lt;/div&gt;\n\n          {% elif t.key == "word" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" required&gt;&lt;/div&gt;\n            &lt;div&gt;&lt;label class="form-label"&gt;Страницы&lt;/label&gt;\n              &lt;input class="form-control" name="pages" placeholder="пусто = все" autocomplete="off"&gt;\n              &lt;div class="hint"&gt;Лучше всего работает с PDF, сделанным из Word или системы. Скан превратится в картинки, а не в текст.&lt;/div&gt;&lt;/div&gt;\n\n          {% elif t.key == "excel" %}\n            &lt;div&gt;&lt;label class="form-label"&gt;PDF&lt;/label&gt;\n              &lt;input class="form-control" type="file" name="files" accept=".pdf" required&gt;&lt;/div&gt;\n            &lt;div&gt;&lt;label class="form-label"&gt;Страницы&lt;/label&gt;\n              &lt;input class="form-control" name="pages" placeholder="пусто = все" autocomplete="off"&gt;&lt;/div&gt;\n            &lt;div class="form-check"&gt;&lt;input class="form-check-input" type="checkbox" name="one_sheet" value="1" id="one_sheet"&gt;\n              &lt;label class="form-check-label" for="one_sheet"&gt;Все таблицы на один лист&lt;/label&gt;\n              &lt;div class="hint"&gt;Иначе каждая таблица — свой лист. Суммы вида «1 234 567,89» становятся числами, номера счетов остаются текстом.&lt;/div&gt;&lt;/div&gt;\n          {% endif %}\n\n            &lt;button class="btn btn-go" type="submit"&gt;&lt;i class="fas fa-download me-1"&gt;&lt;/i&gt;Скачать результат&lt;/button&gt;\n          {% endif %}\n        &lt;/form&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n\n  &lt;div class="rules mt-4"&gt;\n    &lt;b&gt;Как писать страницы:&lt;/b&gt; &lt;code&gt;1-3&lt;/code&gt; — с первой по третью, &lt;code&gt;5&lt;/code&gt; — пятая, &lt;code&gt;8-&lt;/code&gt; — с восьмой до конца,\n    &lt;code&gt;-4&lt;/code&gt; — с первой по четвёртую, &lt;code&gt;5-3&lt;/code&gt; — в обратном порядке. Через запятую: &lt;code&gt;1-3, 5, 8-&lt;/code&gt;.\n    PDF под паролем нужно сначала открыть и сохранить без защиты.\n  &lt;/div&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})
